CREATE TABLE IF NOT EXISTS students(student_id INTEGER PRIMARY KEY,usn TEXT UNIQUE NOT NULL,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,branch TEXT NOT NULL,cgpa REAL NOT NULL CHECK(cgpa BETWEEN 0 AND 10),backlogs INTEGER NOT NULL DEFAULT 0 CHECK(backlogs>=0));
CREATE TABLE IF NOT EXISTS companies(company_id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS job_listings(job_id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL REFERENCES companies(company_id),role TEXT NOT NULL,package_lpa REAL NOT NULL,min_cgpa REAL NOT NULL,max_backlogs INTEGER NOT NULL DEFAULT 0,deadline TEXT);
CREATE TABLE IF NOT EXISTS job_allowed_branches(job_id INTEGER NOT NULL REFERENCES job_listings(job_id),branch TEXT NOT NULL,PRIMARY KEY(job_id,branch));
CREATE TABLE IF NOT EXISTS applications(application_id INTEGER PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(student_id),job_id INTEGER NOT NULL REFERENCES job_listings(job_id),status TEXT NOT NULL DEFAULT 'Applied',applied_on TEXT NOT NULL DEFAULT CURRENT_DATE,UNIQUE(student_id,job_id));
CREATE TABLE IF NOT EXISTS interview_slots(slot_id INTEGER PRIMARY KEY,application_id INTEGER NOT NULL REFERENCES applications(application_id),round TEXT NOT NULL,scheduled_at TEXT NOT NULL,venue TEXT NOT NULL,result TEXT NOT NULL DEFAULT 'Pending');
CREATE TABLE IF NOT EXISTS offers(offer_id INTEGER PRIMARY KEY,application_id INTEGER UNIQUE NOT NULL REFERENCES applications(application_id),package_lpa REAL NOT NULL,status TEXT NOT NULL DEFAULT 'Pending');
